-- D-21 Recall & Withdrawal Program + Crisis Management Plan, all DRAFT:
--   FSQM-023 Product Withdrawal and Recall Program      FSQM-024 Crisis Management Plan
--   FRM-011 Recall and Crisis Contact List              FRM-012 Withdrawal, Recall and Mock Recall Record
--   FRM-013 Crisis Management Review and Test Record
--
-- Four Minor findings: 2.6.3.1, 2.6.3.2, 2.6.4.1, 2.6.4.2. FSQM-023/024 are reserved in the remediation
-- workbook; FRM-011..013 are the next free FRM-0xx numbers. Nothing existed before: no recall procedure,
-- no mock recall, no crisis plan.
--
-- Owner's answers, 2026-10-01: the site co-packs under customers' brands, so the brand owner leads a
-- recall and the site supplies the trace; mock recall target 4 hours; the crisis plan is written around a
-- hurricane / severe storm (the other dangers the Code lists are covered by the general response); no
-- certification body chosen yet. The mock recall on FRM-012 is also FSQM-021's annual trace test (D-20).
-- The controlled documents name positions only; names go on FRM-011 entries.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-023', 'FSQM-024', 'FRM-011', 'FRM-012', 'FRM-013')) then
    raise exception 'a D-21 document number is already in use.';
  end if;
  if (select count(*) from public.sop_documents
       where sop_number in ('FSQM-018', 'FSQM-020', 'FSQM-009', 'FSQM-004', 'FSQM-031', 'FSQM-021', 'FSQM-028', 'FSQM-033', 'SOP-401', 'SOP-2.2.3', 'SOP-11.7.3', 'FRM-007', 'FRM-202', 'FRM-301', 'FRM-520', 'FRM-701', 'FRM-702', 'FRM-703', 'FRM-801', 'FRM-903') and status in ('active', 'draft')) <> 20 then
    raise exception 'a document D-21 names is missing.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-023', 'Product Withdrawal and Recall Program', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '2.6.3.1, 2.6.3.2, 2.6.3.3, 2.6.3.4', true, $q${"purpose": "This program states who starts and runs a product withdrawal or recall, how affected product is found and brought back, who is told and how fast, and how the system is tested every year.", "scope": "All product made on site. The site packs under its customers' brands and every customer collects from the site, so a recall is carried out together with the brand owner. Crises that stop the site from making safe food are covered by FSQM-024.", "definitions": "Withdrawal: removing product from sale or distribution for a reason that does not put anyone's health at risk, or before it reaches consumers.\nRecall: removing product that is or may be unsafe, including from consumers.\nBrand owner: the customer whose label the product carries.\nMock recall: a test of this program, run as if a lot had to be recalled.", "responsibility": "Senior Site Management - starts and manages a withdrawal or recall; tells the brand owner, the authorities, SQFI and the certification body; closes the event.\nSQF Practitioner - traces the affected lots, holds affected product, investigates the root cause, raises the CAPA; runs the annual mock recall and keeps FRM-011 current. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nProduction staff - stop, separate and tag affected product and materials when told.\nThe brand owner - leads the removal of product from its customers and any notice to consumers.", "procedure": ["When this program starts", "• A withdrawal or recall is considered whenever product that has left the site may be unsafe or wrongly labelled: an illness or allergen complaint, a supplier's recall or allergen notice, a CCP deviation or failed release check found after dispatch, a labelling error, or a request from a regulator or from the customer whose brand is on the pack.", "• Whoever learns of it tells Senior Site Management at once. Senior Site Management decides the same day whether to start, and is responsible for initiating and managing the withdrawal or recall; the SQF Practitioner investigates it (SQF 2.6.3.1 i).", "The first steps - the same day", "• Hold: affected product and materials still on site are put on hold on FRM-702 under FSQM-018.", "• Trace: the SQF Practitioner traces the affected lots under FSQM-021 - FRM-520 for the supplier lots in each finished lot, FRM-301 for their receipt, FRM-801 for every customer who collected the lot, how much and when. This is the essential traceability information, and the target is to have it within 4 hours (SQF 2.6.3.1 ii).", "• Record: an FRM-012 record is opened and kept up as the event goes on.", "Deciding, and getting advice", "• The site packs under its customers' brands. Senior Site Management tells the brand owner the same day and decides with them whether it is a withdrawal or a recall. The brand owner leads the removal of product from its own customers and any notice to consumers; the site supplies the lot codes, quantities, dates and the reason, and makes no public statement about a customer's brand without that customer.", "• Advice comes from the FDA recall coordinator, the Florida Department of Agriculture and Consumer Services (FDACS) Division of Food Safety, legal counsel, a food safety consultant, and the supplier when its material is the cause. All are on the contact list, FRM-011 (SQF 2.6.3.1 ii).", "Telling people - the communication plan", "• Who is told, and when (SQF 2.6.3.1 iii):", "◦ Site personnel - the same day: what is on hold and what to do with it.", "◦ Customers (the brand owners) - by phone and then in writing the same day: the product, lot codes, quantities collected and dates, the reason, and what to do with the stock.", "◦ Consumers - through the brand owner, with the information the site supplies.", "◦ Authorities - FDA and FDACS as the law requires. Where there is a reasonable probability of serious harm to health, a Reportable Food Registry report is made to FDA within 24 hours.", "◦ Suppliers - when their material is the cause.", "• SQFI and the certification body are told in writing within 24 hours of identifying a food safety event that needs public notification, or a product recall for any reason. SQFI is told at foodsafetycrisis@sqfi.com. SQFI, the certification body and the regulators are listed on FRM-011 as essential organizations (SQF 2.6.3.1 iv, 2.6.3.4).", "• Every notification is written on FRM-012: who was told, when, how and by whom.", "Getting product back", "• Product that comes back, or is held at a customer, is counted against what was dispatched on FRM-801. Returned product is held on FRM-702, kept apart from good stock, and dealt with under FSQM-018.", "• The lot is reconciled on FRM-012: quantity packed = collected by customers + still on site + retained on FRM-703 + disposed of. Anything unaccounted for is followed up with the brand owner until it is found or explained.", "Investigating and closing", "• The SQF Practitioner investigates the root cause and raises a CAPA on FRM-007 under FSQM-009. The investigation and the actions are recorded (SQF 2.6.3.3).", "• Senior Site Management closes the event on FRM-012 when the product is accounted for, the brand owner and the authorities have nothing outstanding, and the CAPA is raised.", "Testing the system - the mock recall", "• At least once a year the SQF Practitioner runs a mock recall and reviews this program, recorded on FRM-012 (SQF 2.6.3.2).", "• Each test goes both ways: a finished lot is traced back to every supplier lot and its receipt (one step back) and forward to every customer who collected it (one step forward); and an incoming material lot is traced forward to every finished lot it went into and on to those customers.", "• The choice changes each year: a material used across several products, and a lot that went to more than one customer where there is one. The site works a single shift, so the test covers different production days and products instead of different shifts.", "• The contact list, FRM-011, is checked in the same test: every number and address is confirmed current.", "• The test passes when every input is traced, the whole lot is accounted for, and it was done within 4 hours. A miss is raised as a CAPA on FRM-007, and the result goes to the management review.", "Records", "• FRM-012 records of mock recalls and of actual withdrawals and recalls, the CAPAs raised from them and the FRM-011 contact list are kept as SOP-2.2.3 requires (SQF 2.6.3.3)."], "form_references": "FRM-012 - Withdrawal, Recall and Mock Recall Record\nFRM-011 - Recall and Crisis Contact List\nFRM-520 - Production Lot Record\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-801 - Dispatch and Vehicle Loading Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-703 - Retention Sample Log\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "records": "• FRM-012 - one per mock recall and one per actual withdrawal or recall\n• FRM-011 - the current contact list\n• FRM-007 CAPAs raised from a test or an event", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.6.3.1, 2.6.3.2, 2.6.3.3 (Product Withdrawal and Recall), 2.6.3.4 (notifying SQFI and the certification body).\n\nFSQM-021 Product Identification and Traceability Program - the trace.\nFSQM-018 Non-Conforming Product and Equipment - held and returned product.\nFSQM-009 CAPA Program.\nFSQM-024 Crisis Management Plan.\nFSQM-004 Organizational Structure and Responsibilities - the positions named here.\nSOP-2.2.3 Document and Record Control Program - retention.", "revision_history": "New - 2026-10-01 - DRAFT under D-21, for the Minor findings against 2.6.3.1 and 2.6.3.2. The site had no withdrawal or recall procedure and had never run a mock recall.\n\nOWNER'S ANSWERS (2026-10-01): the site co-packs under customers' brands, so the brand owner leads the recall and the site supplies the trace; the mock recall target is 4 hours; no certification body has been chosen yet.\n\nTHE MOCK RECALL IS ALSO D-20's TRACE TEST: FSQM-021 says the annual trace test is part of this test, recorded on FRM-012.\n\nAT ISSUE: activate the 'traceability_test' row on the verification schedule (FSQM-017 Part 6) against FRM-012, yearly; issue FSQM-021 and FRM-520 first or with it.\n\nTO CONFIRM BEFORE ISSUE: (1) the customer agreements do make the brand owner responsible for consumer notices; (2) the certification body, once contracted, added to FRM-011; (3) legal counsel and a food safety consultant named on FRM-011; (4) the first mock recall run and recorded."}$q$::jsonb),
  ('FSQM-024', 'Crisis Management Plan', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '2.6.4.1, 2.6.4.2', true, $q${"purpose": "This plan states how Adventure Bakery copes with an event that stops it making safe food - above all a hurricane - who decides, how affected product is found and checked, and how the site restarts safely.", "scope": "The whole site and everything stored on it. Product that has already left the site is handled under FSQM-023.", "definitions": "Crisis: an event that stops, or threatens, the site's ability to make and deliver safe food.\nCrisis management team: the people who run the response.\nWatch / warning: the National Weather Service's notices that a storm is possible (watch) or expected (warning) in the area.", "responsibility": "Senior Site Management - declares a crisis, makes the decisions, authorizes the restart, and speaks for the site to staff, customers, authorities and the media.\nSQF Practitioner - holds and assesses affected product and materials, runs the restart checks, keeps FRM-011 current, and runs the annual test. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nAll staff - follow the team's instructions and pass every outside enquiry to Senior Site Management.", "procedure": ["The dangers considered", "• Hurricane, tropical storm or other severe weather is the danger most likely to stop the site making safe food: the site is in central Florida (FSQM-028). It brings loss of power and refrigeration, water entering the building, a boil-water notice, and pests afterwards. It has its own part below.", "• Also considered, and handled by the general response below: loss of power or refrigeration on its own (the temperature alerts of SOP-401 raise it), fire, loss of the Team Portal or internet (records are kept on printed forms until it is back), loss of key staff (the backups in FSQM-004), and a pandemic.", "• Not credible for this site: ammonia leak (no ammonia refrigeration), tsunami, drought, warfare.", "Who decides, and the team", "• Senior Site Management is the senior manager responsible for decisions, oversight and starting the response (SQF 2.6.4.1 i).", "• The crisis management team is Senior Site Management and the SQF Practitioner, with the substitute SQF Practitioner standing in. The team is trained on this plan when it is issued and at every annual test; the test record, FRM-013, is the training record (SQF 2.6.4.1 ii).", "The general response - any crisis", "• People first. Once everyone is safe, Senior Site Management declares the crisis and calls the team.", "• Production stops, or does not start, until Senior Site Management says it can.", "• No response is allowed to put product at risk: nothing is made, packed or dispatched while the site has no power to the refrigerator or freezer, no safe water, a building that is not clean and sound, or pest activity. When work restarts, every control applies in full - the CCPs, the pre-operational check on FRM-903 and release on FRM-701 (SQF 2.6.4.1 iii).", "• Everything that was on site during the event - ingredients, packaging, work in progress and finished product - is treated as affected until it has been checked, and is put on hold on FRM-702 with its lot code (SQF 2.6.4.1 iv).", "• Before anything is released, the SQF Practitioner assesses each held lot under FSQM-018: its temperature record, any contact with water, the state of its packaging, and any sign of pests. Product is released only under FSQM-020 on FRM-701. Anything touched by flood or roof water, or chilled or frozen material with a gap in its temperature record that cannot be explained, is disposed of (SQF 2.6.4.1 v).", "• The crisis contact list is FRM-011: the team, the landlord, utilities, the insurer, customers, suppliers and the authorities. It is kept in the Team Portal and as a copy that can be reached when the site and the portal cannot (SQF 2.6.4.1 vi).", "• Legal and expert advice - FDACS, FDA, legal counsel, the insurer and a food safety consultant - is listed on FRM-011 (SQF 2.6.4.1 vii).", "• Senior Site Management alone speaks for the site: to staff, to customers about delays and affected lots, to the authorities, to other organizations and to the media. Staff pass every enquiry on (SQF 2.6.4.1 viii).", "• If product that has already left the site may be affected, FSQM-023 starts.", "Hurricane or severe storm", "• Before the season - by 1 June each year: the plan is reviewed and tested and the contact list checked.", "• Watch - a storm is possible within about two days: Senior Site Management decides what production goes ahead. Whatever is started is finished and packed; no batter or unwrapped product is left. Ingredients and packaging are moved off the floor and away from doors. Customers are asked to collect finished product. Refrigerator and freezer temperatures are noted.", "• Warning or evacuation order: production stops, equipment is cleaned down and unplugged, and the site is closed. Nobody stays.", "• Afterwards, nobody returns until it is safe and allowed. Before any production:", "◦ The building is checked for roof leaks, water on the floor, broken glass (SOP-11.7.3) and pests (FSQM-031).", "◦ The temperature record of the refrigerator and freezer is checked for the whole outage, and their contents dealt with under SOP-401.", "◦ The water is confirmed safe: no production under a boil-water notice (FSQM-033).", "◦ Anything touched by flood or roof water is put on hold and disposed of.", "◦ The site is cleaned and sanitized in full, and the pre-operational check on FRM-903 passed.", "• Senior Site Management then authorizes the restart, and the event is recorded on FRM-013.", "Review and test", "• At least once a year, before 1 June, the team walks through a storm scenario against this plan, checks the contact list, and records the review, who took part, the gaps found and the actions on FRM-013. Gaps are raised as CAPAs on FRM-007 (SQF 2.6.4.2).", "• The plan is also reviewed on FRM-013 after any real crisis.", "Records", "• FRM-013 reviews, tests and actual events, FRM-011 and the FRM-007 CAPAs are kept as SOP-2.2.3 requires (SQF 2.6.4.2)."], "form_references": "FRM-013 - Crisis Management Review and Test Record\nFRM-011 - Recall and Crisis Contact List\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-701 - Finished Product Release Record\nFRM-903 - Daily Sanitation, Pre-Operation & Release Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "records": "• FRM-013 - one per annual review and test, and one per actual crisis\n• FRM-011 - the current contact list\n• FRM-702 holds and FRM-701 releases of affected product", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.6.4.1, 2.6.4.2 (Crisis Management Planning).\n\nFSQM-023 Product Withdrawal and Recall Program.\nFSQM-018 Non-Conforming Product and Equipment; FSQM-020 Product Release Program.\nSOP-401 Temperature-Controlled Storage; FSQM-033 Water Supply Program; FSQM-031 Pest Prevention Program; SOP-11.7.3.\nFSQM-028 Site and Local Environment Risk Assessment.\nFSQM-004 Organizational Structure and Responsibilities.", "revision_history": "New - 2026-10-01 - DRAFT under D-21, for the Minor findings against 2.6.4.1 and 2.6.4.2. The site had no crisis management plan.\n\nOWNER'S DECISION (2026-10-01): the plan is written around the one danger that matters here, a hurricane or severe storm. The other dangers the Code lists were considered and are covered by the general response rather than by parts of their own.\n\nAT ISSUE: add a yearly 'crisis plan review and test' row to the verification schedule (FSQM-017 Part 6) against FRM-013, due before 1 June.\n\nTO CONFIRM BEFORE ISSUE: (1) where the copy of the contact list is kept that can be reached without the site or the portal; (2) the insurer, landlord and utility contacts entered on FRM-011; (3) whether the temperature sensors keep recording through a power cut - if not, chilled and frozen stock after an outage has no record and is disposed of; (4) the first walk-through recorded on FRM-013."}$q$::jsonb),
  ('FRM-011', 'Recall and Crisis Contact List', 'form', 'Module 2', 'draft', 'New',
   '2.6.3.1, 2.6.4.1', true, jsonb_build_object('form_schema', $q${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": false, "requireVerification": true, "instanceTitleTemplate": "Contact list - {reviewed_on}"}, "sections": [{"id": "list", "title": "1. The contact list", "fields": [{"id": "how_this_works", "type": "info", "label": "How to use this", "text": "This is the list used in a recall (FSQM-023) and in a crisis (FSQM-024). Keep one current list: when a contact changes, and at every mock recall and crisis test, copy the last entry, correct it and submit it. Add a line for every customer. Suppliers' contacts are on their FRM-202 approval records."}, {"id": "reviewed_on", "type": "date", "label": "Checked on", "width": "third", "required": true, "showInList": true}, {"id": "off_site_copy", "type": "text", "label": "Where the off-site copy is kept", "width": "half", "help": "A copy that can be reached when the site and the Team Portal cannot"}, {"id": "contacts", "type": "grid", "label": "Contacts", "required": true, "rowDialog": true, "columns": [{"id": "group", "label": "Group", "type": "select", "options": ["Crisis team", "Customer (brand owner)", "Supplier", "Authority", "SQF", "Advice", "Utility / landlord"], "width": 1.2}, {"id": "name", "label": "Person", "type": "text", "width": 1.3, "scanFact": "none"}, {"id": "phone", "label": "Phone", "type": "text", "width": 1.1, "scanFact": "none"}, {"id": "email", "label": "Email", "type": "text", "width": 1.5, "scanFact": "none"}, {"id": "when", "label": "When to contact", "type": "text", "width": 2, "scanFact": "none"}], "rows": {"mode": "fixed", "deletable": true, "labelHeader": "Contact", "addLabel": "Add contact", "labels": ["Senior Site Management", "SQF Practitioner", "Substitute SQF Practitioner", "SQFI", "Certification body", "FDA - recall coordinator / Reportable Food Registry", "FDACS Division of Food Safety", "Legal counsel", "Food safety consultant", "Insurer", "Landlord", "City of Sanford Utilities (water)", "Electricity supplier"], "defaultValues": [{"group": "Crisis team", "when": "Recall coordinator and crisis lead - first call for any event"}, {"group": "Crisis team", "when": "Trace, holds and investigation"}, {"group": "Crisis team", "when": "When the SQF Practitioner is away"}, {"group": "SQF", "when": "In writing within 24 hours of a recall or a food safety event needing public notification", "email": "foodsafetycrisis@sqfi.com"}, {"group": "SQF", "when": "In writing within 24 hours, as for SQFI - to be added when contracted"}, {"group": "Authority", "when": "Recall; Reportable Food Registry report within 24 hours where serious harm is probable"}, {"group": "Authority", "when": "Recall or a crisis affecting the food permit"}, {"group": "Advice", "when": "Recall, or any public statement"}, {"group": "Advice", "when": "Assessing risk and held product"}, {"group": "Advice", "when": "Recall or damage to the site"}, {"group": "Utility / landlord", "when": "Building damage, access, the complex's backflow device"}, {"group": "Utility / landlord", "when": "Boil-water notice, loss of water"}, {"group": "Utility / landlord", "when": "Loss of power"}]}}]}, {"id": "sign", "title": "2. Sign-off", "fields": [{"id": "checked_by", "type": "signature", "label": "Checked by", "role": "filler", "required": true, "statement": "Every number and address on this list was checked and is current."}, {"id": "approved_by", "type": "signature", "label": "Senior Site Management", "role": "verifier", "required": true, "statement": "This is the site's current recall and crisis contact list."}]}]}$q$::jsonb)),
  ('FRM-012', 'Withdrawal, Recall and Mock Recall Record', 'form', 'Module 2', 'draft', 'New',
   '2.6.3.2, 2.6.3.3, 2.6.2.1', true, jsonb_build_object('form_schema', $q${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{record_type} - {lot_codes}"}, "sections": [{"id": "event", "title": "1. The event", "fields": [{"id": "how_this_works", "type": "info", "label": "How to use this", "text": "One record per mock recall test, withdrawal or recall (FSQM-023). For a mock recall, do both directions: a finished lot back to its supplier lots and forward to its customers, and an incoming material lot forward to every finished lot it went into. Work from the records only - FRM-520, FRM-301, FRM-801 - and time it."}, {"id": "record_type", "type": "select", "label": "Type", "width": "third", "required": true, "showInList": true, "options": ["Mock recall test", "Withdrawal", "Recall"]}, {"id": "started", "type": "datetime", "label": "Started", "width": "third", "required": true, "showInList": true}, {"id": "brand_owner", "type": "text", "label": "Customer / brand owner", "width": "third"}, {"id": "product", "type": "text", "label": "Product", "width": "half", "required": true, "showInList": true}, {"id": "lot_codes", "type": "text", "label": "Lot code(s)", "width": "half", "required": true, "showInList": true, "help": "The finished lot(s); for a material-lot test, also write the material and its supplier lot in the reason"}, {"id": "reason", "type": "textarea", "label": "Reason, or test scenario", "required": true}]}, {"id": "back", "title": "2. One step back - what went in", "fields": [{"id": "trace_back", "type": "grid", "label": "Supplier lots in the finished lot (from FRM-520)", "required": true, "columns": [{"id": "ingredient", "label": "Ingredient / material", "type": "text", "required": true, "width": 2, "scanFact": "none"}, {"id": "supplier", "label": "Supplier", "type": "text", "width": 1.5, "scanFact": "none"}, {"id": "supplier_lot", "label": "Supplier lot", "type": "text", "required": true, "width": 1.5, "scanFact": "none"}, {"id": "received", "label": "Received (FRM-301)", "type": "date", "width": 1.2}, {"id": "found", "label": "Receipt record", "type": "select", "options": ["Found", "Not found"], "required": true, "width": 1}], "rows": {"mode": "dynamic", "min": 1, "addLabel": "Add supplier lot"}}]}, {"id": "forward", "title": "3. One step forward - where it went", "fields": [{"id": "trace_forward", "type": "grid", "label": "Customers who collected the lot (from FRM-801)", "help": "For a material-lot test, one line per finished lot and customer. If nothing has left the site, say so in Still on site.", "columns": [{"id": "finished_lot", "label": "Finished lot", "type": "text", "width": 1, "scanFact": "none"}, {"id": "customer", "label": "Customer", "type": "text", "required": true, "width": 2, "scanFact": "none"}, {"id": "quantity", "label": "Quantity", "type": "text", "required": true, "width": 1, "scanFact": "none"}, {"id": "collected", "label": "Collected on", "type": "date", "width": 1.2}], "rows": {"mode": "dynamic", "min": 1, "addLabel": "Add customer"}}, {"id": "qty_packed", "type": "text", "label": "Quantity packed", "width": "third", "required": true}, {"id": "qty_collected", "type": "text", "label": "Collected by customers", "width": "third", "required": true}, {"id": "qty_on_site", "type": "text", "label": "Still on site", "width": "third", "required": true}, {"id": "qty_retained", "type": "text", "label": "Retained (FRM-703) or disposed of", "width": "third", "required": true}, {"id": "qty_unaccounted", "type": "text", "label": "Unaccounted for", "width": "third", "required": true, "help": "Write 0 if the lot is fully accounted for"}]}, {"id": "result", "title": "4. Time and result", "fields": [{"id": "completed", "type": "datetime", "label": "Trace completed", "width": "third", "required": true}, {"id": "within_target", "type": "select", "label": "Within 4 hours", "width": "third", "required": true, "options": ["Yes", "No - CAPA raised"]}, {"id": "contacts_checked", "type": "select", "label": "Contact list (FRM-011)", "width": "third", "required": true, "options": ["Checked - current", "Checked - updated", "Not checked - actual event"]}, {"id": "gaps", "type": "textarea", "label": "Gaps found", "help": "Anything that could not be traced, was slow to find, or was missing from a record. Write None if there were none."}, {"id": "capa_no", "type": "text", "label": "FRM-007 no.", "width": "third"}]}, {"id": "actual", "title": "5. Actual withdrawal or recall only", "description": "Leave blank for a mock recall.", "fields": [{"id": "notifications", "type": "grid", "label": "Who was told", "columns": [{"id": "who", "label": "Who", "type": "text", "width": 2, "scanFact": "none"}, {"id": "when", "label": "Date", "type": "date", "width": 1}, {"id": "time", "label": "Time", "type": "time", "width": 0.8}, {"id": "how", "label": "How", "type": "select", "options": ["Phone", "Email", "Letter", "In person", "Online report"], "width": 1}, {"id": "by", "label": "By", "type": "text", "width": 1.2, "scanFact": "none"}], "rows": {"mode": "dynamic", "min": 1, "addLabel": "Add notification"}}, {"id": "recovered", "type": "textarea", "label": "Product recovered and what was done with it", "help": "Quantities returned or held at customers, the FRM-702 hold, and the disposition under FSQM-018"}, {"id": "root_cause", "type": "textarea", "label": "Root cause"}]}, {"id": "sign", "title": "6. Sign-off", "fields": [{"id": "completed_by", "type": "signature", "label": "Carried out by", "role": "filler", "required": true, "statement": "The trace and the quantities above were taken from the site's records."}, {"id": "closed_by", "type": "signature", "label": "Closed by Senior Site Management", "role": "verifier", "required": true, "statement": "I have reviewed this record and the actions raised from it."}]}]}$q$::jsonb)),
  ('FRM-013', 'Crisis Management Review and Test Record', 'form', 'Module 2', 'draft', 'New',
   '2.6.4.1, 2.6.4.2', true, jsonb_build_object('form_schema', $q${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{record_type} - {date}"}, "sections": [{"id": "review", "title": "1. Review, test or event", "fields": [{"id": "how_this_works", "type": "info", "label": "How to use this", "text": "One record for each annual review and test of the crisis management plan (FSQM-024), done before 1 June, and one for each actual crisis. For the test, the team walks through a storm scenario step by step against the plan. Taking part is the team's training."}, {"id": "record_type", "type": "select", "label": "Type", "width": "third", "required": true, "showInList": true, "options": ["Annual review and test", "Actual crisis"]}, {"id": "date", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true}, {"id": "scenario", "type": "textarea", "label": "Scenario tested, or what happened", "required": true}, {"id": "team_present", "type": "textarea", "label": "Crisis team members who took part", "required": true, "help": "Names and positions - this is their training record"}, {"id": "checks", "type": "grid", "label": "Walked through", "columns": [{"id": "result", "label": "Result", "type": "select", "options": ["Done - no gap", "Gap found", "Not applicable"], "required": true, "width": 1}, {"id": "notes", "label": "Notes", "type": "text", "width": 3, "scanFact": "none"}], "rows": {"mode": "fixed", "labels": ["The plan read through - it still matches the site", "FRM-011 contact list checked and current", "Stopping production and securing the site", "Holding and assessing affected product and materials", "Restart checks - building, power and temperatures, water, pests, cleaning", "Who speaks to staff, customers, authorities and the media"], "labelHeader": "Step"}}]}, {"id": "event", "title": "2. Actual crisis only", "description": "Leave blank for the annual test.", "fields": [{"id": "affected", "type": "textarea", "label": "Product and materials affected, and what was done with them", "help": "Lots held on FRM-702, the assessment, and what was released or disposed of"}, {"id": "restart", "type": "textarea", "label": "Restart checks and the date production restarted"}]}, {"id": "outcome", "title": "3. Gaps and actions", "fields": [{"id": "gaps", "type": "textarea", "label": "Gaps found and changes needed to the plan", "required": true, "help": "Write None if there were none"}, {"id": "capa_no", "type": "text", "label": "FRM-007 no.", "width": "third"}]}, {"id": "sign", "title": "4. Sign-off", "fields": [{"id": "completed_by", "type": "signature", "label": "Recorded by", "role": "filler", "required": true, "statement": "This is what was reviewed, tested or done."}, {"id": "approved_by", "type": "signature", "label": "Senior Site Management", "role": "verifier", "required": true, "statement": "I have reviewed this record; the plan is verified, or the gaps above are being acted on."}]}]}$q$::jsonb));

do $verify$
declare p jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-023';
  if jsonb_array_length(p) <> 33 then raise exception 'FSQM-023 procedure is % lines, expected 33.', jsonb_array_length(p); end if;
  if (select count(*) from unnest(array['2.6.3.1 i)', '2.6.3.1 ii)', '2.6.3.1 iii)', '2.6.3.1 iv', '2.6.3.2', '2.6.3.3', '2.6.3.4']) c where p::text like '%' || c || '%') <> 7 then
    raise exception 'FSQM-023 does not cite every limb of 2.6.3.';
  end if;
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-024';
  if jsonb_array_length(p) <> 33 then raise exception 'FSQM-024 procedure is % lines, expected 33.', jsonb_array_length(p); end if;
  if (select count(*) from unnest(array['2.6.4.1 i)', '2.6.4.1 ii)', '2.6.4.1 iii)', '2.6.4.1 iv)', '2.6.4.1 v)', '2.6.4.1 vi)', '2.6.4.1 vii)', '2.6.4.1 viii)', '2.6.4.2']) c where p::text like '%' || c || '%') <> 9 then
    raise exception 'FSQM-024 does not cite every limb of 2.6.4.';
  end if;
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-023', 'FSQM-024', 'FRM-011', 'FRM-012', 'FRM-013')
              and content::text ~* 'Diana|Gabriela|Christina|GJM|Mercer') then
    raise exception 'a D-21 document names a person; controlled documents name positions.';
  end if;
  if (select count(*) from public.sop_documents where sop_number in ('FRM-011', 'FRM-012', 'FRM-013') and content->'form_schema'->'sections' is not null) <> 3 then
    raise exception 'a D-21 form has no schema.';
  end if;
  if (select jsonb_array_length(f->'rows'->'labels') from public.sop_documents d, jsonb_array_elements(d.content->'form_schema'->'sections') s,
             jsonb_array_elements(s->'fields') f where d.sop_number = 'FRM-011' and f->>'id' = 'contacts') <> 13 then
    raise exception 'FRM-011 does not carry its 13 seeded contacts.';
  end if;
end $verify$;

commit;
